// Generated by OpenAI Codex on 2026-11-03. Destination-first walking navigation.
import { useEffect, useId, useRef, useState } from 'react';

const controlStyle = {
  padding: '6px 10px',
  margin: '4px 8px',
  border: '1px solid #aeb9c4',
  borderRadius: 6,
  background: '#f4f7fa',
  color: '#172b3a',
  cursor: 'pointer',
};

const api = process.env.EXPO_PUBLIC_API_URL || 'http://localhost:8000/api';
type Location = { id: string; name: string; matched_name: string; category: string };
export type WalkingRoute = {
  geometry: { coordinates: [number, number][] };
  properties: {
    distance_m: number;
    duration_minutes: number;
    has_stairs: boolean;
    steps: { feature_id: string; name: string; distance_m: number }[];
  };
};

function LocationSearch({
  label,
  onSelect,
  autoFocus = false,
}: {
  label: string;
  onSelect: (location: Location) => void;
  autoFocus?: boolean;
}) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<Location[]>([]);
  const [active, setActive] = useState(0);
  const [open, setOpen] = useState(true);
  const [status, setStatus] = useState('');
  const id = useId();
  const input = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (autoFocus) input.current?.focus();
  }, [autoFocus]);
  useEffect(() => {
    const controller = new AbortController();
    if (!query.trim()) return;
    const timer = setTimeout(async () => {
      try {
        const response = await fetch(`${api}/map/search?q=${encodeURIComponent(query.trim())}`, {
          credentials: 'include',
          signal: controller.signal,
        });
        if (!response.ok) throw new Error('Search unavailable. Try again.');
        const data = await response.json();
        if (controller.signal.aborted) return;
        setResults(data.results);
        setStatus(data.results.length ? '' : 'No matching locations. Try another name.');
      } catch (error) {
        if (!controller.signal.aborted) setStatus((error as Error).message);
      }
    }, 200);
    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query]);
  useEffect(() => {
    if (open) document.getElementById(`${id}-${active}`)?.scrollIntoView({ block: 'nearest' });
  }, [active, open, id]);
  function choose(location: Location) {
    setOpen(false);
    onSelect(location);
  }
  return (
    <div
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setOpen(false);
      }}
    >
      <label htmlFor={`${id}-input`}>{label}</label>
      <input
        ref={input}
        id={`${id}-input`}
        role="combobox"
        aria-autocomplete="list"
        aria-expanded={open && !!query.trim()}
        aria-controls={id}
        aria-activedescendant={open && results[active] ? `${id}-${active}` : undefined}
        value={query}
        maxLength={120}
        placeholder="Search a building or location…"
        autoComplete="off"
        style={{
          display: 'block',
          width: '100%',
          boxSizing: 'border-box',
          padding: 10,
          fontSize: 16,
        }}
        onFocus={() => setOpen(true)}
        onChange={(event) => {
          setQuery(event.target.value);
          setActive(0);
          setStatus(event.target.value.trim() ? 'Searching…' : '');
          setResults([]);
          setOpen(true);
        }}
        onKeyDown={(event) => {
          if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
            event.preventDefault();
            setOpen(true);
            setActive(
              Math.max(
                0,
                Math.min(results.length - 1, active + (event.key === 'ArrowDown' ? 1 : -1)),
              ),
            );
          } else if (event.key === 'Enter' && open && results[active]) {
            event.preventDefault();
            choose(results[active]);
          } else if (event.key === 'Escape') setOpen(false);
        }}
      />
      {open && query.trim() && (
        <div id={id} role="listbox" aria-label={`${label} suggestions`}>
          {results.map((location, index) => (
            <button
              key={location.id}
              id={`${id}-${index}`}
              type="button"
              role="option"
              aria-selected={active === index}
              tabIndex={-1}
              onMouseDown={(event) => event.preventDefault()}
              onMouseEnter={() => setActive(index)}
              onClick={() => choose(location)}
              style={{
                display: 'block',
                width: '100%',
                padding: 9,
                textAlign: 'left',
                border: '1px solid #ddd',
                background: active === index ? '#dcecf9' : 'white',
                color: '#172b3a',
              }}
            >
              <strong>{location.name}</strong>{' '}
              <small>· {location.category.replaceAll('_', ' ')}</small>
              {location.matched_name !== location.name && (
                <div>Also known as {location.matched_name}</div>
              )}
            </button>
          ))}
        </div>
      )}
      {status && <div role="status">{status}</div>}
    </div>
  );
}

export default function NavigationPanel({
  onRoute,
}: {
  onRoute: (route: WalkingRoute | null) => void;
}) {
  const [destination, setDestination] = useState<Location | null>(null);
  const [start, setStart] = useState<Location | null>(null);
  const [route, setRoute] = useState<WalkingRoute | null>(null);
  const [status, setStatus] = useState('');
  useEffect(() => {
    const controller = new AbortController();
    if (!start || !destination) return;
    (async () => {
      try {
        const params = new URLSearchParams({ start: start.id, destination: destination.id });
        const response = await fetch(`${api}/map/route?${params}`, {
          credentials: 'include',
          signal: controller.signal,
        });
        const data = await response.json();
        if (!response.ok)
          throw new Error(typeof data.detail === 'string' ? data.detail : 'Route unavailable.');
        if (controller.signal.aborted) return;
        setRoute(data);
        onRoute(data);
        setStatus('');
      } catch (error) {
        if (!controller.signal.aborted) setStatus((error as Error).message);
      }
    })();
    return () => controller.abort();
  }, [start, destination, onRoute]);
  function clearRoute() {
    setRoute(null);
    onRoute(null);
    setStatus('');
  }
  return (
    <section
      aria-label="Walking navigation"
      style={{
        background: 'white',
        fontFamily: 'system-ui, sans-serif',
        fontSize: 14,
        lineHeight: 1.5,
        color: '#172b3a',
        padding: 12,
        maxHeight: '45vh',
        overflowY: 'auto',
        flexShrink: 0,
      }}
    >
      {!destination ? (
        <LocationSearch label="Where do you want to go?" onSelect={setDestination} />
      ) : (
        <>
          <div>
            <strong>To: {destination.name}</strong>{' '}
            <button
              style={controlStyle}
              onClick={() => {
                clearRoute();
                setDestination(null);
                setStart(null);
              }}
            >
              Change destination
            </button>
          </div>
          {!start ? (
            <LocationSearch
              label="Starting location"
              autoFocus
              onSelect={(location) => {
                clearRoute();
                setStatus('Finding a walking route…');
                setStart(location);
              }}
            />
          ) : (
            <div>
              From: {start.name}{' '}
              <button
                style={controlStyle}
                onClick={() => {
                  clearRoute();
                  setStart(null);
                }}
              >
                Change start
              </button>
            </div>
          )}
        </>
      )}
      {status && <p role="status">{status}</p>}
      {route && (
        <div aria-live="polite">
          <strong>
            {route.properties.distance_m} m · About {route.properties.duration_minutes} min walking
          </strong>
          {route.properties.has_stairs && <div>This route includes stairs.</div>}
          <details>
            <summary>Walking path segments</summary>
            <ol>
              {route.properties.steps.map((step, i) => (
                <li key={`${step.feature_id}-${i}`}>
                  {step.name} · {step.distance_m} m
                </li>
              ))}
            </ol>
          </details>
          <small>
            Uses connected mapped paths and entrances. Check signs and current conditions.
          </small>
        </div>
      )}
    </section>
  );
}
